mapper.select:
SELECT * FROM `order` 
WHERE publisher_id = #{publisherId}
ORDER BY create_time DESC

SELECT * FROM `order` 
WHERE receiver_id = #{receiverId}
ORDER BY create_time DESC

mapper.update:
UPDATE `order` 
SET status = 3, deliver_time = #{deliverTime}
WHERE id = #{id} AND status = 2

UPDATE `order` 
SET status = 4, 
    actual_reward = #{actualReward},
    complete_time = #{completeTime}
WHERE id = #{id}

UPDATE `order` 
SET status = 5, cancel_reason = #{cancelReason}
WHERE id = #{id}

mapper.select:
SELECT * FROM `order`
WHERE status = 3 AND deliver_time < #{beforeTime}
ORDER BY deliver_time ASC

SELECT * FROM `order`
WHERE status = 1 AND deadline < #{now}
ORDER BY deadline ASC

mapper.update:
UPDATE `order`
SET rights_status = #{rightsStatus},
    rights_remark = #{rightsRemark},
    rights_fund_to = #{rightsFundTo},
    rights_review_time = #{rightsReviewTime}
WHERE id = #{id}

mapper.select:
SELECT * FROM `order`
WHERE review_status = #{reviewStatus}
ORDER BY create_time DESC
